/**
 * @brief Метод установки пароля защиты приватного ключа RSA
 *
 * @param password пароль защиты приватного ключа RSA
 *
 */
void awh::Crypto::passwordRSA(string_view password) noexcept {
	// Если объект собран не был
	if(!this->ready())
		// Выходим из метода
		return;
	/**
	 * Выполняем отлов ошибок
	 */
	try {
		/**
		 * Предел выдачи пароля библиотекой криптографии отвергается: выписка ключа
		 * берёт пароль с указанием длины и потому принимает всякий, а буфер выдачи
		 * при вычитывании отведён библиотекой по своей мерке. Пароль длиннее защитил
		 * бы ключ целиком, а обратно подавался бы обрезанным - и ключ, только что
		 * выписанный, тем же объектом не открывался. Довод тот же, что и у пароля с
		 * нулевым октетом (5.32), и отказ здесь по той же причине: работа, у которой
		 * запись и чтение расходятся, работой не является
		 */
		// Если длина пароля защиты приватного ключа предел выдачи превышает
		if(password.size() > static_cast <size_t> (PEM_BUFSIZE)){
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug("Private key password size exceeds the limit of the cryptography library", __PRETTY_FUNCTION__, make_tuple(password.size()), log_t::flag_t::CRITICAL);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print("Private key password size exceeds the limit of the cryptography library", log_t::flag_t::CRITICAL);
			#endif
			// Выходим из функции
			return;
		}
		/**
		 * Новое значение собирается прежде правки объекта, а не поверх затёртого:
		 * присвоение отводит память и потому способно отказать, а к поре отказа
		 * прежнее значение было уже погашено. Объект оставался с нулями в поле, и
		 * следующая выдача ключа защитила бы его нулевым паролем, никому о том не
		 * сообщив. Стейт AES этот пароль не трогает вовсе и сбрасывать его незачем -
		 * тем и отличается порядок здесь от порядка у пароля шифрования данных (3.9)
		 */
		// Собираем новое значение прежде правки объекта
		string value(password);
		/**
		 * Прежний пароль защиты приватного ключа затирается: строка стандартной библиотеки при записи
		 * поверх содержимое не гасит, и прежнее значение оставалось лежать в памяти
		 * до тех пор, покуда её не выдадут кому-то ещё. Гасится вся ёмкость, а не
		 * длина: короткое значение поверх длинного оставило бы хвост прежнего
		 */
		// Выполняем затирание прежнего значения
		secret::erase(this->_params.passwordRSA);
		/**
		 * Перенос отведения памяти не требует и отказать не может, поэтому объект
		 * правится им одним. Собранное значение затирается следом по всей его ёмкости,
		 * а не по длине: короткие строки лежат внутри самого объекта строки, и перенос
		 * оттуда их не убирает, а длину при этом обнуляет - затирание по длине не
		 * тронуло бы ничего
		 */
		// Переносим собранное значение
		this->_params.passwordRSA = ::move(value);
		// Выполняем затирание собранного значения
		secret::erase(value);
	/**
	 * Если возникает ошибка
	 */
	} catch(const exception & error) {
		/**
		 * Если включён режим отладки
		 */
		#if DEBUG_MODE
			// Записываем ошибку в лог
			this->_log->debug("%s", __PRETTY_FUNCTION__, {}, log_t::flag_t::CRITICAL, error.what());
		/**
		 * Если режим отладки не включён
		 */
		#else
			// Записываем ошибку в лог
			this->_log->print("%s", log_t::flag_t::CRITICAL, error.what());
		#endif
	}
}
/**
 * @brief Метод преобразования 128-битного хэша в 64-битный
 *
 * @param hash 128-битный хэш
 * @return     64-битный хэш
 *
 */
uint64_t awh::Crypto::hash128to64(const uint128_t & hash) const noexcept {
	// Первая половина 128-битного хэша
	uint64_t value1 = 0;
	// Вторая половина 128-битного хэша
	uint64_t value2 = 0;
	// Копируем первую половину 128-битного хэша
	::memcpy(&value1, hash.data(), sizeof(value1));
	// Копируем вторую половину 128-битного хэша
	::memcpy(&value2, hash.data() + sizeof(value1), sizeof(value2));
	// Выводим свёртку половин 128-битного хэша
	return hashing::avalanche(hashing::mix(value1, value2));
}
/**
 * @brief Шаблон метода хэширования текста
 *
 * @tparam T тип возвращаемого результата
 *
 */
template <typename T>
/**
 * @brief Метод хэширования текста
 *
 * @param buffer буфер данных для хэширования
 * @param hash   тип хэш-суммы
 * @param format вид записи выработанной хэш-суммы
 * @return       результат хэширования
 *
 */
auto awh::Crypto::hash(string_view buffer, const hash_t hash, const format_t format) const noexcept -> T {
	// Охранник очереди ошибок библиотеки криптографии
	const driver::purge_t purge;
	// Переменная результата
	T result;
	// Если текст передан
	if(!buffer.empty()){
		// Выполняем хэширование
		driver::hash(buffer, hash, format, result, this->_log);
		// Если хэширование не вышло
		if(result.empty()){
			/**
			 * Если включён режим отладки
			 */
			#if DEBUG_MODE
				// Записываем ошибку в лог
				this->_log->debug(
					"Hashing of the text of %zu octets could not be performed",
					__PRETTY_FUNCTION__, make_tuple(
						buffer.size(),
						static_cast <uint16_t> (hash)
					), log_t::flag_t::WARNING,
					buffer.size()
				);
			/**
			 * Если режим отладки не включён
			 */
			#else
				// Записываем ошибку в лог
				this->_log->print(
					"Hashing of the text of %zu octets could not be performed",
					log_t::flag_t::WARNING,
					buffer.size()
				);
			#endif
		}
	}
	// Возвращаем результат работы функции
	return result;
}
